package com.socialblog.comment.repository;import com.socialblog.comment.domain.Comment;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;
public interface CommentRepository extends JpaRepository<Comment,UUID>{Page<Comment>findByArticleIdOrderByCreatedAtAsc(UUID article,Pageable pageable); Page<Comment>findByArticleIdAndStatusOrderByCreatedAtAsc(UUID article,Comment.Status status,Pageable pageable); @org.springframework.data.jpa.repository.Query("SELECT c FROM Comment c WHERE c.articleId = :article AND c.status = :status AND ((:targetUrl IS NULL AND c.targetUrl IS NULL) OR (c.targetUrl = :targetUrl)) ORDER BY c.createdAt ASC") Page<Comment> findByArticleAndTargetUrl(@org.springframework.data.repository.query.Param("article") UUID article, @org.springframework.data.repository.query.Param("targetUrl") String targetUrl, @org.springframework.data.repository.query.Param("status") Comment.Status status, Pageable pageable);}
